<script setup lang="ts">
import { onMounted, ref } from 'vue';import{ElMessageBox,ElMessage}from'element-plus';import{api}from'@/api';
const tab=ref('tasks');const loading=ref(false);const tasks=ref<any[]>([]);const health=ref<any>({components:{}});const resilience=ref<any>({});const statusFilter=ref('');
const load=async()=>{loading.value=true;try{const[taskRows,healthResult,resilienceResult]=await Promise.all([api.get('/tasks/',{params:{status:statusFilter.value}}),api.get('/system/readiness/').catch((error:any)=>error.response?.data||{components:{}}),api.get('/system/resilience/').catch(()=>({}))]);tasks.value=taskRows;health.value=healthResult;resilience.value=resilienceResult}finally{loading.value=false}};
const action=async(row:any,name:'retry'|'cancel')=>{const{value}=await ElMessageBox.prompt(`请输入${name==='retry'?'重试':'取消'}任务原因`,'任务操作',{inputType:'textarea'});await api.post(`/tasks/${row.id}/${name}/`,{operation_reason:value},{headers:{'Idempotency-Key':crypto.randomUUID()}});ElMessage.success(name==='retry'?'任务已重新入队。':'任务已取消。');await load()};onMounted(load);
</script>
<template><div class="page" v-loading="loading"><header class="page-header"><div><h1>任务与系统健康</h1><p>统一处理真实队列任务、失败原因和组件 readiness，不用静态状态掩盖故障。</p></div><el-button @click="load">重新探测</el-button></header><el-tabs v-model="tab" style="margin-top:18px"><el-tab-pane label="异步任务" name="tasks"><div class="toolbar"><el-select v-model="statusFilter" clearable placeholder="任务状态" @change="load"><el-option v-for="item in ['pending','running','review_required','succeeded','failed','canceled']" :key="item" :label="item" :value="item" /></el-select></div><div class="data-surface"><el-table :data="tasks"><el-table-column prop="title" label="任务" min-width="220" /><el-table-column prop="owner_email" label="所有者" min-width="190" /><el-table-column prop="status" label="状态" width="110" /><el-table-column prop="progress" label="进度" width="90"><template #default="{row}">{{row.progress}}%</template></el-table-column><el-table-column prop="error_message" label="错误" min-width="240" show-overflow-tooltip /><el-table-column label="操作" width="140"><template #default="{row}"><el-button v-if="row.status==='failed'||row.retryable" link type="primary" @click="action(row,'retry')">重试</el-button><el-button v-if="['pending','running'].includes(row.status)" link type="danger" @click="action(row,'cancel')">取消</el-button></template></el-table-column></el-table></div></el-tab-pane><el-tab-pane label="Agent 韧性" name="resilience"><section class="metric-band"><div class="metric"><span>等待投递</span><strong>{{resilience.dispatch_outbox?.pending||0}}</strong><small>事务 Outbox</small></div><div class="metric"><span>生成中</span><strong>{{resilience.executions?.generating||0}}</strong><small>PostgreSQL durable state</small></div><div class="metric"><span>可重试失败</span><strong>{{resilience.executions?.failed_retryable||0}}</strong><small>自动恢复</small></div><div class="metric"><span>陈旧执行</span><strong>{{resilience.stale_execution_count||0}}</strong><small>超过执行租期</small></div></section><div class="resilience-grid"><div><h3>Execution 状态</h3><pre>{{JSON.stringify(resilience.executions||{},null,2)}}</pre></div><div><h3>幂等声明</h3><pre>{{JSON.stringify(resilience.idempotency||{},null,2)}}</pre></div><div><h3>缓存指标</h3><pre>{{JSON.stringify(resilience.cache_metrics||{},null,2)}}</pre></div></div></el-tab-pane><el-tab-pane label="组件健康" name="health"><div class="health-grid"><div v-for="(item,name) in health.components" :key="name"><el-tag :type="item.ok?'success':'danger'">{{item.ok?'正常':'不可用'}}</el-tag><strong>{{name}}</strong><small>{{item.latency_ms??'-'}}ms · {{item.reason||(item.critical?'关键组件':'可降级组件')}}</small></div></div></el-tab-pane></el-tabs></div></template>
<style scoped>.health-grid,.resilience-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.health-grid>div,.resilience-grid>div{display:grid;gap:8px;padding:16px;border:1px solid #dfe3e8;border-radius:5px;background:#fff}.health-grid .el-tag{width:fit-content}.health-grid small{color:#667085}.resilience-grid{margin-top:18px}.resilience-grid h3{margin:0}.resilience-grid pre{margin:0;white-space:pre-wrap}</style>
